const product = $('Webhook — Données produit + fournisseur').first().json;
const claudeResponse = $('Claude — Copywriting complet').first().json;

// Extraire le JSON depuis la réponse Claude
const rawText = claudeResponse?.content?.[0]?.text || claudeResponse?.content || '';

let content;
try {
  // Nettoyer si Claude a quand même mis du markdown
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  content = JSON.parse(cleaned);
} catch(e) {
  // Fallback : extraire le JSON avec regex
  const match = rawText.match(/\{[\s\S]*\}/);
  if (match) {
    content = JSON.parse(match[0]);
  } else {
    throw new Error('Impossible de parser la réponse Claude : ' + rawText.substring(0, 200));
  }
}

// Traduire les reviews en français
const reviews = (product.reviews_raw || []).map(r => ({
  ...r,
  text_fr: r.text_original // sera traduit par un node suivant si nécessaire
}));

return [{
  json: {
    ...product,
    content,
    reviews_translated: reviews,
    ready_for_import: true
  }
}];

