const product = $('Parser la réponse Claude').first().json;
const claudeReviewsRaw = $('Claude — Traduire reviews en FR').first().json?.content?.[0]?.text || '[]';

let reviewsFr = [];
try {
  const cleaned = claudeReviewsRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  reviewsFr = JSON.parse(cleaned);
} catch(e) {
  reviewsFr = product.reviews_raw?.slice(0, 5).map(r => ({
    rating: r.rating,
    text_fr: r.text_original,
    author: r.author,
    country: r.country
  })) || [];
}

return [{
  json: {
    ...product,
    reviews_fr: reviewsFr,
    pipeline_stage: 'READY_FOR_SHOPIFY_IMPORT'
  }
}];
